SELECT analytics_order_facts.customer_segment, SUM(analytics_order_facts.contribution_margin) AS contribution_margin FROM analytics_order_facts WHERE analytics_order_facts.year = 2024 AND analytics_order_facts.month = 7 AND analytics_order_facts.region = 'South' AND analytics_order_facts.channel = 'marketplace' GROUP BY analytics_order_facts.customer_segment ORDER BY contribution_margin DESC, analytics_order_facts.customer_segment ASC LIMIT 12
